const selectionMode = msg.payload?.selectionMode === 'multiple' ? 'multiple' : 'single';
const options = [
  { id: 'option_a', label: 'A — Action-led', description: 'The person and moment of action are primary.' },
  { id: 'option_b', label: 'B — Context-led', description: 'The environment and atmosphere are primary.' },
  { id: 'option_c', label: 'C — Balanced', description: 'Equal emphasis on person, action, and environment.' }
];
msg.mcpResult = {
  content: [{ type: 'text', text: 'Choose one or more creative directions.' }],
  structuredContent: { title: 'Choose creative variants', selectionMode, options, allowCustomFeedback: true },
  _meta: { ui: { resourceUri: 'ui://creative-picker/variants.html' } }
};
return msg;

const allowed = new Set(['option_a', 'option_b', 'option_c']);
const input = msg.payload || {};
const selectedIds = Array.isArray(input.selectedIds) ? [...new Set(input.selectedIds.filter(id => typeof id === 'string'))] : [];
const selectionMode = input.selectionMode === 'multiple' ? 'multiple' : 'single';
const invalid = selectedIds.filter(id => !allowed.has(id));
if (!selectedIds.length || invalid.length || (selectionMode === 'single' && selectedIds.length !== 1)) {
  msg.mcpResult = { content: [{ type: 'text', text: 'Invalid creative-picker selection.' }], isError: true };
  return msg;
}
const feedback = typeof input.feedback === 'string' ? input.feedback.trim().slice(0, 2000) : '';
msg.mcpResult = {
  content: [{ type: 'text', text: `Selected: ${selectedIds.join(', ')}.` }],
  structuredContent: { selectedIds, selectionMode, feedback, message: 'Selection saved for the current conversation only.' }
};
return msg;
